(()=>{
 const natural=[0,2,4,5,7,9,11],sharps=[3,0,4,1,5,2,6],flats=[6,2,5,1,4,0,3];
 function alterations(sf){const a=Array(7).fill(0);for(const l of (sf<0?flats:sharps).slice(0,Math.abs(sf)))a[l]=Math.sign(sf);return a}
 const spellingCache=new Map();
 function spell(p,sf){const cacheKey=p+":"+sf;if(spellingCache.has(cacheKey))return spellingCache.get(cacheKey);const key=alterations(sf);let best=null;for(let oct=Math.floor(p/12)-2;oct<=Math.floor(p/12);oct++)for(let l=0;l<7;l++){const accidental=p-((oct+1)*12+natural[l]);if(Math.abs(accidental)>1)continue;const cost=4*Math.abs(accidental-key[l])+(accidental===0?0:1)+(accidental&&Math.sign(accidental)!==Math.sign(sf||1)?.25:0);if(!best||cost<best.cost)best={letter:l,octave:oct,step:(oct+1)*7+l,accidental,cost}}spellingCache.set(cacheKey,best);return best}
 function spellNote(n,sf){const h=n.spelling;if(h&&Number.isInteger(h.step)&&[-1,0,1].includes(h.accidental)){const letter=((h.step%7)+7)%7,octave=Math.floor(h.step/7)-1;if((octave+1)*12+natural[letter]+h.accidental===n.p)return{letter,octave,step:h.step,accidental:h.accidental,upper:h.upper,cost:0}}return spell(n.p,sf)}
 function noteName(n,sf){const x=spellNote(n,sf);return 'CDEFGAB'[x.letter]+(x.accidental===1?'♯':x.accidental===-1?'♭':'')+x.octave}
 function layout(notes,key,changes=[],meters=[]){let defaults=alterations(key.sf),section=0;const state=new Map(),out=Array(notes.length);for(const {n,i}of notes.map((n,i)=>({n,i})).sort((a,b)=>a.n.s-b.n.s||a.i-b.i)){while(section<changes.length&&changes[section].s<=n.s){key=changes[section++];defaults=alterations(key.sf)}const x=spellNote(n,key.sf),upper=x.upper??(n.p>=60),id=section+':'+(window.MidiMeter?window.MidiMeter.barAt(meters,n.s).index:Math.floor(n.s/4))+':'+upper+':'+x.step,previous=state.has(id)?state.get(id):defaults[x.letter];out[i]={...x,key,upper,glyph:x.accidental===previous?'':x.accidental===0?'♮':x.accidental===1?'♯':'♭'};state.set(id,x.accidental)}return out}
 function name(key){const major=['C♭','G♭','D♭','A♭','E♭','B♭','F','C','G','D','A','E','B','F♯','C♯'],minor=['A♭','E♭','B♭','F','C','G','D','A','E','B','F♯','C♯','G♯','D♯','A♯'];return(key.minor?minor:major)[key.sf+7]+(key.minor?' 小調':' 大調')}
 function analyze(tracks,preferred={sf:0,minor:0},changes=[],meters=[]){const melodic=tracks.filter(t=>t.ch%16!==9&&t.notes.length),ordered=melodic.map(t=>t.notes.map((n,i)=>({n,i})).sort((a,b)=>a.n.s-b.n.s||a.i-b.i));const scores=[];for(let sf=-7;sf<=7;sf++){let count=0;for(const notes of ordered){let section=0,current={sf},defaults=alterations(sf);const state=new Map();for(const {n}of notes){while(section<changes.length&&changes[section].s<=n.s){current=changes[section++];defaults=alterations(current.sf)}const x=spellNote(n,current.sf),id=section+':'+(window.MidiMeter?window.MidiMeter.barAt(meters,n.s).index:Math.floor(n.s/4))+':'+(x.upper??(n.p>=60))+':'+x.step,previous=state.has(id)?state.get(id):defaults[x.letter];if(x.accidental!==previous)count++;state.set(id,x.accidental)}}scores.push({sf,count})}scores.sort((a,b)=>a.count-b.count||Math.abs(a.sf)-Math.abs(b.sf)||(a.sf===preferred.sf?-1:b.sf===preferred.sf?1:a.sf-b.sf));const best=scores[0],minor=best.sf===preferred.sf?preferred.minor||0:0;return{key:{sf:best.sf,minor},count:best.count,cMajorCount:scores.find(x=>x.sf===0).count,tracks:melodic.length,notes:ordered.reduce((n,t)=>n+t.length,0),scores}}
 window.StaffNotation={alterations,spell,spellNote,noteName,layout,name,analyze};
})();
